-- ============================================================================
-- 003_languages_and_translations.sql - the site's own words, in the database
-- ============================================================================
-- What the site itself says to a member - its navigation, the dashboard, the
-- import wizard and its guides, the account and character pages, the words of
-- a recommendation, an import's errors and warnings - is read from these
-- tables, in English and in Slovak. The words are rows rather than files in
-- the build because they are reworded in the browser: a file of the Angular
-- build is overwritten by the next upload, and the host has no shell to edit
-- one with. So a string is a key the code names, and a value per language
-- that the owner may reword.
--
-- ONE migration holds the tables, the two languages and every string, on
-- purpose. A pending migration does not close this site (an admin applies it
-- on the Sources page), and a file applies whole or not at all: there is never
-- a database with the tables and no strings, which would put keys on every
-- page. Until this file is applied the site reads the English compiled into
-- the app, and every translation route answers 503 translations_unavailable.
--
-- Which keys there are is the code's business: migrations write them, the
-- browser only ever changes values. That is why a key has no "created by", and
-- why a value written by a migration has nobody in updated_by.
--
-- English is what every other language falls back to, string by string, so it
-- is always here and always on. There is no flag for HTML on a string and no
-- such thing on the site: a string is text, and is drawn as text.
--
-- The game's own words are never rows here: stat names and abbreviations,
-- character, weapon and set names, slot and talent names, "Lv.", "4pc", UID.
-- They reach a sentence as a {placeholder} or stand before a colon. And no
-- string names another website, service or tool - seeded or reworded.
--
-- The names of the constraints follow 002 ({table}_pkey, {table}_{column}_foreign,
-- {table}_{column}_check). No existing table is altered: imports, the dashboard
-- and everything else work on a database that has not seen this file.
-- ============================================================================

-- ── The languages ───────────────────────────────────────────────────────────
-- A code is what a browser and the IAM's token call the language ("sk",
-- "pt-br" - always small letters here); the names are for people: `name` in
-- English for the owner's pages, `native_name` for the chooser a reader sees.
-- A language switched off is no longer offered, and keeps its strings.
CREATE TABLE IF NOT EXISTS languages (
    code        VARCHAR(10)     NOT NULL,
    name        VARCHAR(50)     NOT NULL,               -- in English: "Slovak"
    native_name VARCHAR(50)     NOT NULL,               -- as its speakers write it: "Slovenčina"
    enabled     BOOLEAN         NOT NULL DEFAULT TRUE,
    sort_order  INTEGER         NOT NULL DEFAULT 0,
    CONSTRAINT languages_pkey PRIMARY KEY (code),
    CONSTRAINT languages_code_check CHECK (code ~ '^[a-z]{2}(-[a-z]{2})?$')
);

-- ── The keys ────────────────────────────────────────────────────────────────
-- description: where the string is shown and what its {placeholders} stand
-- for - all a translator has to go by.
CREATE TABLE IF NOT EXISTS translation_keys (
    name        VARCHAR(200)    NOT NULL,
    description TEXT,
    created_at  TIMESTAMPTZ     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT translation_keys_pkey PRIMARY KEY (name)
);

-- ── The strings ─────────────────────────────────────────────────────────────
-- One string: a key in a language. There is no empty one - a language that has
-- no string for a key has no row, and reads the English. updated_by is the IAM
-- user id of whoever last reworded it in the browser; null: as a migration
-- wrote it. It is a plain number with no foreign key to users: who a person is
-- belongs to the IAM, and a row of users may go without its strings going too.
CREATE TABLE IF NOT EXISTS translations (
    key_name      VARCHAR(200)  NOT NULL,
    language_code VARCHAR(10)   NOT NULL,
    value         TEXT          NOT NULL,
    updated_at    TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by    BIGINT,
    CONSTRAINT translations_pkey PRIMARY KEY (key_name, language_code),
    CONSTRAINT translations_key_name_foreign FOREIGN KEY (key_name)
        REFERENCES translation_keys (name) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT translations_language_code_foreign FOREIGN KEY (language_code)
        REFERENCES languages (code) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT translations_value_check CHECK (value <> '')
);

-- ── The two languages the site is released in ───────────────────────────────
-- They cannot be deleted in the browser (App\Services\Translations\TranslationCheck::SEEDED):
-- a later migration with strings would fail on a missing language.
INSERT INTO languages (code, name, native_name, sort_order) VALUES
    ('en', 'English', 'English', 1),
    ('sk', 'Slovak', 'Slovenčina', 2)
ON CONFLICT (code) DO NOTHING;

-- ── Every key, with its English and its Slovak string ───────────────────────
-- They go here, above the gate, in three statements - the shape the tests read
-- (tests/translation_catalogue.test.php) and every later string migration
-- follows:
--
--   1. the keys, a row each, by namespace: ('namespace.key', 'where it is shown
--      and what its {placeholders} stand for'), into translation_keys (name,
--      description), ending in a line "ON CONFLICT (name) DO NOTHING;"
--   2. the English strings: into translations (key_name, language_code, value),
--      as "SELECT v.key_name, 'en', v.value FROM (VALUES" ... rows of
--      ('namespace.key', 'The string') ... ") AS v(key_name, value)", ending in
--      a line "ON CONFLICT (key_name, language_code) DO NOTHING;"
--   3. the Slovak strings, the same with 'sk'.
--
-- One row on a line, its key first; an apostrophe written twice and nothing
-- else escaped (no E'' strings): that is all the statement splitter
-- (App\Db\Migrator::splitStatements) knows of a string. Keys ending in .one,
-- .few and .other are the forms of one plural, asked for by the family's name
-- with a {count}; English says in .few what it says in .other. Slovak speaks to
-- the reader informally ("ty"). The English strings are, key for key, the
-- English compiled into the app (frontend/src/app/core/i18n/).
--
-- Every insert steps aside for a row that is already there: a string reworded
-- in the browser is the owner's and is never written over. So a string added
-- or reworded after this file was released is a migration of its own, never an
-- edit of this file - and expected_keys below is the number of keys this file
-- seeds.

