    ('import.status.success', 'The status chip of an import run in an account''s import history: everything was imported. One lower-case word about the import. No placeholders.'),
    ('import.status.partial', 'The status chip of an import run in an account''s import history: the import went through with warnings. One lower-case word about the import. No placeholders.'),
    ('import.status.failed', 'The status chip of an import run in an account''s import history: the import failed. One lower-case word about the import. No placeholders.'),
    -- common (the shell part)
    ('common.close', 'A button that closes what is open: the What''s-new dialog, and the action of a snack bar that stays until it is dismissed (an error on the dashboard or the account page). No placeholders.'),
    ('common.cancel', 'A button that gives something up without doing it: beside Save when an account is being renamed, and the "no" of the question before an account is deleted. No placeholders.'),
    ('common.save', 'The account page: the button that saves the account''s new name. No placeholders.'),
    ('common.retry', 'The dashboard, in the panel shown when its data could not be loaded: the button that asks the server again. No placeholders.'),
    ('common.signIn', 'The button that goes to the sign-in: in the toolbar while nobody is signed in, and on the sign-in page. No placeholders.'),
    ('common.signOut', 'The button that signs the person out: in the toolbar''s account menu, and on the sign-in page for an account that has no access. No placeholders.'),
    ('common.userFallback', 'What stands in place of a person''s name when their account has neither a user name nor an email address: in the toolbar beside the account icon, and inside the sign-in page''s sentence "Your anotoki account … has no access". {sub}: the account''s number at the sign-in service, shown as it is. The Slovak is only „č. {sub}“ so that it also reads well inside that sentence („Tvoj anotoki účet č. 7 …“).'),
    -- nav (the shell part)
    ('nav.dashboard', 'The toolbar, on every page: the link to the start page with the person''s game accounts. On a narrow screen only its icon shows. No placeholders.'),
    ('nav.import', 'The toolbar, on every page: the link to the import wizard. On a narrow screen only its icon shows. No placeholders.'),
    ('nav.builds', 'The toolbar, on every page: the link to the recommended builds of every character. On a narrow screen only its icon shows. No placeholders.'),
    ('nav.sources', 'The toolbar, for an admin: the link to the Sources page (the page itself is English). Also the link inside the dashboard''s sentence "Start the first sync on the … page", and the name other strings use for that page. No placeholders.'),
    -- toolbar (the shell part)
    ('toolbar.syncing', 'The toolbar, while this browser tab is driving a build sync: the tooltip of the spinning sync icon, which links to the Sources page. The sync stops when the tab is closed. No placeholders.'),
    ('toolbar.syncingLabel', 'The toolbar, while this browser tab is driving a build sync: the accessible name of the spinning sync icon (what a screen reader says). No placeholders.'),
    ('toolbar.version', 'The toolbar: the accessible name of the version button ("v0.2"), which opens the What''s-new dialog. {version}: the version number, shown as it is ("0.2").'),
    ('toolbar.yourAccount', 'The toolbar, signed in: the accessible name of the button with the person''s name, which opens the account menu. No placeholders.'),
    ('toolbar.account', 'The toolbar''s account menu: the link to the person''s anotoki account page (profile, password, sessions), which opens in a new tab. No placeholders.'),
