    ('whatsNew.added', 'The What''s-new dialog: the heading above what a release added. No placeholders.'),
    ('whatsNew.fixed', 'The What''s-new dialog: the heading above what a release fixed. No placeholders.'),
    ('whatsNew.updated', 'The What''s-new dialog: the heading above what a release changed. No placeholders.'),
    -- confirm (the shell part)
    ('confirm.deleteAccount', 'The question asked before a game account is deleted from the dashboard: the title of the dialog. {name}: the account''s name as the person gave it, or "UID" and the player''s number when it has none - shown as it is, inside quotation marks.'),
    ('confirm.deleteAccountKept', 'The question asked before a game account is deleted: the line under the title, saying that the recommended builds (which are shared by everybody) stay. No placeholders.'),
