    ('dashboard.moreActions', 'The dashboard, under an account''s card: the accessible name of the three-dot button that opens the card''s menu. No placeholders.'),
    ('dashboard.deleteAccount', 'The dashboard, in an account card''s menu: deletes the game account after a question. No placeholders.'),
    ('dashboard.deleted', 'The dashboard: a snack bar after a game account was deleted. {name}: the account''s name as the person gave it, or "UID" and the player''s number - shown as it is.'),
    ('dashboard.sources', 'The dashboard: the heading of the section that lists the build sources ("Source 1", "Source 2" …) with how many characters each has builds for. No placeholders.'),
    ('dashboard.manageSources', 'The dashboard, for an admin: the link beside the "Build sources" heading, to the Sources page. No placeholders.'),
