    ('dashboard.sourceCharacters.other', 'The dashboard, in the row of a build source: how many characters it has builds for - the form for 0 and for 5 or more. {count}: that number.'),
    ('dashboard.syncing', 'The dashboard, at the end of a build source''s row, while that source is being synced - in place of the time of its last sync. Lower case: it stands where a relative time would. No placeholders.'),
    ('dashboard.notSyncedYet', 'The dashboard, at the end of a build source''s row, in place of the time of its last sync when it has never been synced. Lower case: it stands where a relative time ("3 hours ago") would. No placeholders.'),
    -- account (the shell part)
    ('account.nameLabel', 'The account page, while the account is being renamed: the label of the text field. No placeholders.'),
    ('account.rename', 'The account page: the accessible name of the pencil button beside the account''s name. No placeholders.'),
    ('account.renameShort', 'The account page: the tooltip of the pencil button beside the account''s name. No placeholders.'),
    ('account.imported', 'The account page, at the end of the line under the account''s name (after the game, the UID and the level, separated by dots): when its data was last imported. Lower case: it continues that line. {when}: a relative time in the page''s language, such as "3 hours ago" / „pred 3 hodinami“.'),
    ('account.notImportedYet', 'The account page, at the end of the line under the account''s name, in place of "imported …" when the account has no import time. Lower case: it continues that line. No placeholders.'),
    ('account.updateByUid', 'The account page: the button that opens the import wizard to read the account again from the game''s Character Showcase, by the player''s number. "UID" is the games'' word and stays as it is. No placeholders.'),
    ('account.uploadInventory', 'The account page: the button that opens the import wizard to upload an inventory export file for this account. No placeholders.'),
