    ('importWizard.target.new', 'The import wizard (/import), step Import of a file: the first choice of the "Import into" list. "UID" is the game''s word and stays as it is. No placeholders.'),
    ('importWizard.target.accountUid', 'The import wizard (/import), step Import: one of the person''s accounts in the "Import into" list. {name}: the account''s name as the person wrote it. {uid}: its UID, digits. "UID" is the game''s word and stays as it is.'),
    ('importWizard.target.accountNoUid', 'The import wizard (/import), step Import by UID: one of the person''s accounts in the "Import into" list that has no UID yet (it was imported from a file). {name}: the account''s name as the person wrote it. "UID" is the game''s word and stays as it is.'),
    ('importWizard.target.showcaseHint', 'The import wizard (/import), step Import by UID: the hint under the "Import into" list. "UID" is the game''s word and stays as it is. No placeholders.'),
    ('importWizard.target.fileHint', 'The import wizard (/import), step Import of a file: the hint under the "Import into" list. {weapons}: the game''s word, "Weapons" or "Light Cones". {items}: the game''s word, "Artifacts" or "Relics". Both are never translated or declined - in Slovak they stand after the colon.'),
    ('importWizard.file.heading', 'The import wizard (/import), step Import of a file: the heading. No placeholders.'),
