    -- builds (the builds part)
    ('builds.title', 'The Builds page (/builds/{game}): its heading. No placeholders.'),
    ('builds.subtitle', 'The Builds page: the line under the heading. No placeholders.'),
    ('builds.game', 'The Builds page: the accessible name of the switch between the two games (its buttons are the games'' names, which are not strings). No placeholders.'),
    ('builds.search', 'The Builds page: the label of the search field. {game} is the game''s name, "Genshin Impact" or "Honkai: Star Rail" - never translated or declined.'),
    ('builds.count.one', 'How many builds a character has: on a character''s card of the Builds page (before " · Source 1, Source 2") and under the name on a character''s builds page (/builds/{game}/{key}). Plural family, the form for 1. {count} is the number.'),
    ('builds.count.few', 'How many builds a character has (see builds.count.one). Plural family, the form for 2-4 in Slovak. {count} is the number.'),
    ('builds.count.other', 'How many builds a character has (see builds.count.one). Plural family, the form for 0 and 5 or more. {count} is the number.'),
    ('builds.empty', 'The Builds page when no character has a build yet. {link} is where the link to the Sources page stands; its text is builds.sourcesPage. A language may leave {link} out - then no link is drawn.'),
    ('builds.sourcesPage', 'The text of the link to the Sources page inside builds.empty and character.noBuilds. It is that page''s name: keep it the same word as the toolbar''s link to it. No placeholders.'),
    ('builds.allCharacters', 'A character''s builds page (/builds/{game}/{key}): the link back to the Builds page, after a back arrow. No placeholders.'),
    -- character (the builds part)
    ('character.talentBonus', 'The character page (/accounts/{id}/characters/{key}), the header: the tooltip of a talent''s chip when the level is raised by the character''s rank. {bonus} is the number of levels; {ranks} is the game''s term "Constellations" or "Eidolons" - never translated or declined, so no Slovak word may have to agree with it.'),
    ('character.versus', 'The character page, the header: under the overall score, which build the score is measured against. {build} is the source''s stored name and the build''s name, "Source 1 · Main DPS" - kept as they are.'),
    ('character.noBuilds', 'The character page when no source has a build for this character. {name} is the character''s name (never declined: keep it first or after a colon); {link} is where the link to the Sources page stands, its text is builds.sourcesPage. A language may leave {link} out - then no link is drawn.'),
    ('character.closestMatch', 'The character page, the tabs of the builds: the tooltip of the star on the build that fits the character''s equipment best. No placeholders.'),
    ('character.scoreBreakdown', 'The character page: the heading of the panel with the five parts of the score. No placeholders.'),
    ('character.score.targets', 'The character page, "Score breakdown": the label of the bar for the stat values the build aims for. The other four bars are labelled with the game''s terms (Weapon / Light Cone, Set bonuses, Main stats, Substats), which are not strings. No placeholders.'),
    ('character.targetsNeedTotals', 'The character page, "Score breakdown": shown when the build has stat targets and the account has no in-game totals to check them with. UID and Character Showcase are the game''s terms and stay as they are. No placeholders. In Slovak an import by UID is „import zadaním UID“ and the game''s totals „celkové hodnoty z hry“, as on every page.'),
    ('character.yourWeapon', 'The character page, "Score breakdown": the label before the name of the weapon the character has equipped. {weapon_label} is the game''s term "Weapon" or "Light Cone" - never translated or declined, so no Slovak word may have to agree with it (no "tvoj / tvoja"). The colon is part of the string.'),
    ('character.weaponOption', 'The character page, after the equipped weapon''s level ("Lv. 90 · "): where that weapon stands on the build''s list. {rank} is its place, {total} how many the list has.'),
    ('character.weaponNotListed', 'The character page, after the equipped weapon''s level ("Lv. 90 · "): the build''s list does not have that weapon. Lower case: it continues a line. No placeholders.'),
    ('character.improve', 'The character page: the heading of the list of recommendations. No placeholders.'),
    ('character.category.sets', 'The character page, a recommendation''s small heading: it is about the sets the character wears. (The headings Weapon / Light Cone, Talents / Traces, Main stat and Substats are the game''s terms, not strings.) No placeholders.'),
    ('character.category.targets', 'The character page, a recommendation''s small heading: it is about a stat value the build aims for. No placeholders.'),
    ('character.category.levels', 'The character page, a recommendation''s small heading: it is about levelling the character. No placeholders.'),
    ('character.category.unknown', 'The character page, a recommendation''s small heading when the server names a category this version of the site does not know. No placeholders.'),
    ('character.nothingToChange', 'The character page: shown in place of the recommendations when the build has none. No placeholders.'),
    ('character.yourItems', 'The character page: the heading above the pieces the character wears. {items} is the game''s term "Artifacts" or "Relics" - never translated or declined, so no Slovak word may have to agree with it (no "tvoje").'),
    ('character.critValue', 'The character page, Genshin Impact only: a chip beside the heading of the pieces. "Crit value" is the players'' own term and stays as it is; {value} is the number, in the game''s notation ("182.4").'),
    ('character.critValueHint', 'The character page: the tooltip of the "Crit value" chip - how the number is made. {crit_rate} and {crit_dmg} are the game''s stat names "CRIT Rate" and "CRIT DMG", {items} the game''s term "Artifacts" - none translated or declined.'),
    ('character.legend', 'The character page: the legend above the pieces the character wears. "Substats" is the game''s term and stays as it is. {color} is where one word stands drawn in the highlight colour; that word is character.legendColor. A language may leave {color} out - then the coloured word is not drawn. In Slovak no preposition stands before {color} (v / vo would change with the word): „čo je {color}, … čo je sivé“.'),
    ('character.legendColor', 'The one word of character.legend that is drawn in the highlight colour, in the form that sentence needs. No placeholders. In Slovak an adjective, „farebné“, standing like „sivé“ later in that sentence.'),
    ('character.nothingEquipped', 'The character page: in the place of a piece when the slot is empty, under the slot''s name. No placeholders.'),
    ('character.betterOwned', 'The character page: the heading of the pieces from the player''s inventory that would serve the build better. No placeholders.'),
    ('character.nothingBetter', 'The character page, under "Better pieces you already own" when the inventory has none. "To farm" is the players'' word for playing for new pieces. No placeholders.'),
    ('character.switchTo', 'The character page: the heading of a plan to change to the build''s top set with pieces already owned. {set} is the set with its pieces, "4pc Crimson Witch of Flames" - the game''s words, never declined: keep it after a colon.'),
    ('character.planOwned.one', 'The character page, a set plan: how many of the pieces the set bonus needs the player owns. Plural family on the number NEEDED, the form for 1. {owned} is how many are owned, {count} how many are needed.'),
    ('character.planOwned.few', 'The character page, a set plan: owned and needed pieces (see character.planOwned.one). The form for 2-4 needed in Slovak. {owned} is how many are owned, {count} how many are needed.'),
    ('character.planOwned.other', 'The character page, a set plan: owned and needed pieces (see character.planOwned.one). The form for 0 and 5 or more needed. {owned} is how many are owned, {count} how many are needed.'),
    ('character.currentlyOn', 'The character page, under a suggested piece: another character wears it now. {character} is that character''s name - never declined: keep it after a colon.'),
    ('character.notEquipped', 'The character page, under a suggested piece: no character wears it. No placeholders.'),
    ('character.planMissing.one', 'The character page, under a set plan when the player owns fewer pieces than the set bonus needs. Plural family on the number still missing, the form for 1. {count} is that number.'),
    ('character.planMissing.few', 'The character page, under a set plan: pieces still missing (see character.planMissing.one). The form for 2-4 in Slovak. {count} is the number.'),
    ('character.planMissing.other', 'The character page, under a set plan: pieces still missing (see character.planMissing.one). The form for 0 and 5 or more. {count} is the number.'),
    ('character.reason.betterSubstats.one', 'The character page, the chip on a suggested piece: its substats are better than the worn piece''s by this many points of the site''s 0-100 quality score. Plural family on the points, the form for 1. {count} is the number. "Substats" is the game''s term and stays as it is.'),
    ('character.reason.betterSubstats.few', 'The character page, the chip on a suggested piece: better substats (see character.reason.betterSubstats.one). The form for 2-4 in Slovak. {count} is the number of points.'),
    ('character.reason.betterSubstats.other', 'The character page, the chip on a suggested piece: better substats (see character.reason.betterSubstats.one). The form for 0 and 5 or more. {count} is the number of points.'),
    ('character.reason.completesSet', 'The character page, the chip on a suggested piece: with it the character has the set bonus the build recommends. "Set bonus" is the game''s term and stays as it is; no Slovak word may have to agree with it. No placeholders.'),
    ('character.reason.fixesMainStat', 'The character page, the chip on a suggested piece: it has the main stat the build recommends. "Main stat" is the game''s term and stays as it is; no Slovak word may have to agree with it. No placeholders.'),
    ('character.reason.unknown', 'The character page, the chip on a suggested piece when the server gives a reason this version of the site does not know. No placeholders.'),
    ('character.currentPiece', 'The character page, under a suggested piece: how good the piece worn now is. {percent} is the site''s own 0-100 score of it (not a game value), so Slovak writes the sign after a space.'),
    ('character.uploadInventory', 'The character page, in place of the suggestions when the account was imported without its whole inventory. No placeholders.'),
    ('character.consensus.title', 'The character page: the heading of the panel that counts what the builds of all sources have in common. No placeholders.'),
    ('character.consensus.builds.one', 'The character page, under "What the sources agree on": how many builds were counted, and from which sources. Plural family on the builds, the form for 1 (the panel is shown from 2 builds up, so this form is not met today). {count} is the number; {sources} the sources'' stored names joined with commas, "Source 1, Source 2" - kept as they are: keep them after a colon.'),
    ('character.consensus.builds.few', 'The character page: how many builds were counted and from which sources (see character.consensus.builds.one). The form for 2-4 in Slovak. {count} is the number, {sources} the sources'' names.'),
    ('character.consensus.builds.other', 'The character page: how many builds were counted and from which sources (see character.consensus.builds.one). The form for 0 and 5 or more. {count} is the number, {sources} the sources'' names.'),
    ('character.consensus.sets', 'The character page, "What the sources agree on": the label of a row of sets whose kind this version of the site does not know. (The known kinds are labelled with the game''s terms Artifact sets, Cavern Relics and Planar Ornaments, which are not strings.) No placeholders.'),
    ('character.consensus.bestWeapon', 'The character page, "What the sources agree on": the label of the row of weapons the builds rank first. {weapon_label} is the game''s term "Weapon" or "Light Cone" - never translated or declined, so no Slovak word may have to agree with it (no "najlepší / najlepšia" beside it).'),
    ('character.stats.title', 'The character page: the heading of the panel with the character''s stat values. No placeholders.'),
    ('character.stats.fromShowcase', 'The character page, the stats panel: the values are the game''s own totals, read from the in-game Character Showcase (the game''s term, kept as it is). {when} is how long ago, already in the page''s language as an adverbial ("3 hours ago" / "pred 3 hodinami"). In Slovak the game''s totals are „celkové hodnoty z hry“, as in the import wizard.'),
    ('character.stats.fromFile', 'The character page, the stats panel: the values are the game''s own totals, read from the inventory file the player uploaded. {when} is how long ago, already in the page''s language as an adverbial ("3 hours ago" / "pred 3 hodinami"). In Slovak the game''s totals are „celkové hodnoty z hry“, as in the import wizard.'),
    ('character.stats.inGame', 'The character page, the stats panel: the values are the game''s own totals, and it is not known when they were read. No placeholders. In Slovak the game''s totals are „celkové hodnoty z hry“, as in the import wizard.'),
    ('character.stats.itemsOnly', 'The character page, the stats panel when the account has no in-game totals: what follows is only the sum of the worn pieces. {items} is the game''s term "Artifacts" or "Relics" - never translated or declined, so no Slovak word may have to agree with it. UID stays as it is. The colon is part of the string: a table follows. In Slovak an import by UID is „import zadaním UID“ and the game''s totals „celkové hodnoty z hry“, as on every page.'),
    -- buildDetail (the builds part)
    ('buildDetail.noWeapons', 'A build''s detail (on a character''s builds page and on the character page), under the heading Weapons / Light Cones (the game''s term, not a string) when the source recommends none. Do not write a word that would have to agree with that heading. No placeholders.'),
    ('buildDetail.equipped', 'A build''s detail on the character page: the chip on the weapon of the list that the character has equipped. No placeholders.'),
    ('buildDetail.owned', 'A build''s detail on the character page: the chip on a weapon of the list that the player owns and does not use on this character. No placeholders.'),
    ('buildDetail.setsQualify.one', 'A build''s detail, under a set option one of whose places any of several sets can fill. Plural family on the number of sets, the form for 1 (shown from 2 up, so this form is not met today). {label} is that place''s stored name, "ATK +18% set" - kept as it is, first and before a colon; {count} is the number of sets.'),
    ('buildDetail.setsQualify.few', 'A build''s detail: how many sets can fill a place of a set option (see buildDetail.setsQualify.one). The form for 2-4 in Slovak. {label} is the place''s stored name, {count} the number of sets.'),
    ('buildDetail.setsQualify.other', 'A build''s detail: how many sets can fill a place of a set option (see buildDetail.setsQualify.one). The form for 0 and 5 or more. {label} is the place''s stored name, {count} the number of sets.'),
    ('buildDetail.inUse', 'A build''s detail on the character page: the chip on the set option the character wears. No placeholders.'),
    ('buildDetail.mainStatMatches', 'A build''s detail on the character page, under the heading Main stats: the tooltip of the check mark on a slot whose piece has a recommended main stat. "Main stat" is the game''s term and stays as it is; no Slovak word may have to agree with it (no "tvoj"). No placeholders.'),
    ('buildDetail.mainStatYours', 'A build''s detail on the character page, under the heading Main stats: the tooltip of the cross on a slot whose piece has another main stat. {stat} is that stat''s name in the game''s words, "ATK%" - or "-" when the slot is empty.'),
    ('buildDetail.substatPriority', 'A build''s detail: the heading of the substats in the order the build wants them. "Substat" is the game''s term: in Slovak it stays "Substats", first and before a colon. No placeholders.'),
    ('buildDetail.substatsBorrowed', 'A build''s detail, under "Substat priority" when the source gives no order of substats. No placeholders.'),
    ('buildDetail.talentPriority', 'A build''s detail: the heading of the talents in the order the build levels them. {talents} is the game''s term "Talents" or "Traces" - never translated or declined: keep it first and before a colon.'),
    ('buildDetail.statTargets', 'A build''s detail: the heading of the stat values the build aims for. No placeholders.'),
    ('buildDetail.targetYours', 'A build''s detail on the character page, in a stat target''s row after the target ("70.0%+"): the character''s own value. Lower case: it continues a row. {value} is the value in the game''s notation, "62.0%".'),
    ('buildDetail.notesFrom', 'A build''s detail: the title of the panel that opens the source''s own notes (the notes themselves are shown as the source wrote them, in English). {source} is the source''s stored name, "Source 1" - kept as it is: keep it after a colon.'),
    ('buildDetail.version', 'A build''s detail, the foot: the game''s version the build was written for. {version} is that version, "5.2".'),
    ('buildDetail.updatedAtSource', 'A build''s detail, the foot: when the source last changed the build. {when} is how long ago, already in the page''s language as an adverbial ("3 days ago" / "pred 3 dňami").'),
    ('buildDetail.checked', 'A build''s detail, the foot: when a sync last read the build at its source. {when} is how long ago, already in the page''s language as an adverbial ("3 hours ago" / "pred 3 hodinami").'),
    ('buildDetail.checkedNever', 'A build''s detail, the foot: no sync has read the build at its source yet. No placeholders.'),
    -- item (the builds part)
    ('item.percentOfIdealForBuild', 'A piece''s card (an artifact or relic, on the character page): the tooltip of its grade. {percent} is the site''s own 0-100 score of the piece (not a game value), so Slovak writes the sign after a space.'),
    ('item.wrongMainStat', 'A piece''s card: the tooltip of the warning beside a main stat the build does not recommend. "Main stat" is the game''s term and stays as it is; no Slovak word may have to agree with it (no "iný" beside it). No placeholders.'),
    ('item.percentOfIdeal', 'A piece''s card, the foot: the piece''s score. {percent} is the site''s own 0-100 score (not a game value), so Slovak writes the sign after a space.'),
    ('item.grade', 'The accessible name of a grade''s badge, wherever one is shown (a piece, a character, a build). {grade} is the letter S, A, B, C or D, or "-" for none - kept as it is: keep it after a colon.'),
    ('item.noScore', 'A score bar (the five parts of a build''s score, on the character page and the account page): in the place of the number when that part could not be scored. Short - it stands where a number of at most three digits does. No placeholders.')
ON CONFLICT (name) DO NOTHING;

