-- ============================================================================
-- PROVE IT
--
-- Both languages are here and English is on; the tables carry the constraints
-- they should, under their names, and a deleted key or language takes its
-- strings with it; every key reads in both languages, and there are exactly
-- as many keys as this file seeds.
-- ============================================================================
DO $$
DECLARE
    expected_keys CONSTANT INTEGER := 406;
    found INTEGER;
    wrong TEXT;
BEGIN
    SELECT string_agg(wanted.code, ', ' ORDER BY wanted.code) INTO wrong
      FROM (VALUES ('en'), ('sk')) AS wanted(code)
     WHERE NOT EXISTS (SELECT 1 FROM languages l WHERE l.code = wanted.code);
    IF wrong IS NOT NULL THEN
        RAISE EXCEPTION 'Languages that should be here and are not: %', wrong;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM languages WHERE code = 'en' AND enabled) THEN
        RAISE EXCEPTION 'English is switched off, and every other language falls back to it';
    END IF;

    WITH expected (name, kind) AS (VALUES
        ('languages_pkey', 'p'), ('languages_code_check', 'c'),
        ('translation_keys_pkey', 'p'),
        ('translations_pkey', 'p'), ('translations_value_check', 'c'),
        ('translations_key_name_foreign', 'f'), ('translations_language_code_foreign', 'f')
    )
    SELECT string_agg(e.name, ', ') INTO wrong
      FROM expected e
     WHERE NOT EXISTS (SELECT 1 FROM pg_constraint c
                        JOIN pg_namespace n ON n.oid = c.connamespace AND n.nspname = current_schema()
                       WHERE c.conname = e.name AND c.contype::TEXT = e.kind);
    IF wrong IS NOT NULL THEN
        RAISE EXCEPTION 'Constraints missing: %', wrong;
    END IF;

    -- A deleted key or language takes its strings with it, and a renamed one keeps them.
    SELECT string_agg(c.conname, ', ') INTO wrong
      FROM pg_constraint c
     WHERE c.conname IN ('translations_key_name_foreign', 'translations_language_code_foreign')
       AND (c.confdeltype::TEXT <> 'c' OR c.confupdtype::TEXT <> 'c');
    IF wrong IS NOT NULL THEN
        RAISE EXCEPTION 'Foreign keys that do not cascade: %', wrong;
    END IF;

    -- updated_by points at no table: the strings do not depend on a row of users.
    SELECT count(*) INTO found FROM pg_constraint WHERE conrelid = 'translations'::regclass AND contype = 'f';
    IF found <> 2 THEN
        RAISE EXCEPTION 'translations has % foreign keys, not the two it should have', found;
    END IF;

    SELECT string_agg(k.name, ', ' ORDER BY k.name) INTO wrong
      FROM translation_keys k
     WHERE NOT EXISTS (SELECT 1 FROM translations t WHERE t.key_name = k.name AND t.language_code = 'en')
        OR NOT EXISTS (SELECT 1 FROM translations t WHERE t.key_name = k.name AND t.language_code = 'sk');
    IF wrong IS NOT NULL THEN
        RAISE EXCEPTION 'Keys without an English and a Slovak string: %', wrong;
    END IF;

    SELECT count(*) INTO found FROM translation_keys;
    IF found <> expected_keys THEN
        RAISE EXCEPTION 'There are % keys, and this file seeds %', found, expected_keys;
    END IF;
END $$;
